118: type EnvRecord = Record<string, string | undefined>
119: 
120: function readEnv(): EnvRecord {
121:   return import.meta.env as EnvRecord
122: }
123: 
124: /** 每次读取 import.meta.env，便于单测 stub 与 .env.test 隔离 */
125: export function getApiBase(): string {
126:   const env = readEnv()
127:   return env.VITE_API_BASE_URL ?? env.VITE_AUTH_BASE_URL ?? ''
128: }
129: 
130: export function getProjectId(): string {
131:   return readEnv().VITE_PROJECT_ID ?? 'suzhufang'
132: }
133: 
134: export function isConfigured() {
135:   return Boolean(getApiBase())
136: }
137: 
138: /** 网关图形验证码：GET /v2.0/code（与 main 分支 getCodeImg → /api/v2.0/code 一致） */
139: export interface LoginCaptchaPayload {
140:   enabled: boolean
141:   uuid?: string
142:   imageDataUrl?: string
143: }
144: 
145: export async function fetchLoginCaptcha(): Promise<LoginCaptchaPayload> {
146:   // 图形验证码仅暴露于后端网关，demo 模式下也走同源 /api 反代（nginx 已代理 /api → 网关）。
147:   const apiBase = getApiBase() || '/api'
148:   const url = `${apiBase.replace(/\/$/, '')}/v2.0/code`
149:   const response = await uniTransport({
150:     url,
151:     method: 'GET',
152:     header: { Accept: 'application/json, text/plain, */*', 'zhi-project-id': getProjectId() },
153:     timeout: 20000,
154:   })
155:   if (response.statusCode < 200 || response.statusCode >= 300) {
156:     throw new Error(`验证码加载失败（HTTP ${response.statusCode}）`)
157:   }
158:   const body = response.data as {
159:     code?: number
160:     msg?: string
161:     captchaOnOff?: boolean
162:     uuid?: string
163:     data?: string
164:   } | null
165:   if (body && typeof body === 'object' && 'code' in body && body.code !== 200) {
166:     throw new Error(body.msg || '验证码加载失败')
167:   }
168:   const enabled = body?.captchaOnOff !== false && Boolean(body?.uuid && body?.data)
169:   if (!enabled) return { enabled: false }
170:   const raw = String(body!.data)
171:   const imageDataUrl = raw.startsWith('data:') ? raw : `data:image/jpeg;base64,${raw}`
172:   return { enabled: true, uuid: String(body!.uuid), imageDataUrl }
173: }
174: // 统一网关前缀（/api + /v2.0/...，对齐 main 分支 request 封装）
175: export const request = createRequest(uniTransport, {
176:   baseUrl: getApiBase,
177:   projectId: getProjectId,
178:   getToken,
179: })
180: /** @deprecated 与 request 同源，保留别名避免旧引用报错 */
181: export const authRequest = request
