183: /**
184:  * H5 带鉴权下载文件流（PDF 等）。
185:  * window.open 直接导航不会携带 Authorization 头，后端会返回 401「令牌不能为空」；
186:  * 这里用原生 fetch 手动注入 Bearer + zhi-project-id，拿到 blob 后用临时 <a download> 触发下载。
187:  */
188: export async function downloadFileWithAuth(path: string, filename: string): Promise<void> {
189:   const apiBase = getApiBase()
190:   if (!apiBase) throw new Error('真实接口未配置：请设置 VITE_API_BASE_URL')
191:   const url = `${apiBase.replace(/\/$/, '')}/${path.replace(/^\//, '')}`
192:   const headers: Record<string, string> = { 'zhi-project-id': getProjectId() }
193:   const token = getToken()
194:   if (token) headers.Authorization = `Bearer ${token}`
195:   const resp = await fetch(url, { headers })
196:   if (!resp.ok) {
197:     let msg = `下载失败（HTTP ${resp.status}）`
198:     try { const j = await resp.json(); if (j && j.msg) msg = String(j.msg) } catch { /* 非 JSON 错误体，保留默认文案 */ }
199:     throw new Error(msg)
200:   }
201:   const blob = await resp.blob()
202:   const objectUrl = URL.createObjectURL(blob)
203:   const a = document.createElement('a')
204:   a.href = objectUrl
205:   a.download = filename
206:   document.body.appendChild(a)
207:   a.click()
208:   a.remove()
209:   setTimeout(() => URL.revokeObjectURL(objectUrl), 1500)
210: }

